def parse_duration(s: str) -> int:
    m = re.fullmatch(r'[ ]*(?:(\d+)d)?[ ]*(?:(\d+)h)?[ ]*(?:(\d+)m)?[ ]*(?:(\d+)s)?[ ]*', s)
    if not m:
        raise ValueError("Invalid duration string")

    d = int(m.group(1)) if m.group(1) else None
    h = int(m.group(2)) if m.group(2) else None
    m_val = int(m.group(3)) if m.group(3) else None
    s_val = int(m.group(4)) if m.group(4) else None

    if d is None and h is None and m_val is None and s_val is None:
        raise ValueError("At least one component is required")

    return (d or 0) * 86400 + (h or 0) * 3600 + (m_val or 0) * 60 + (s_val or 0)

