        if c == '*':
            for j in range(t_len + 1):
                if j == 0:
                    new_dp[0] = dp[0]
                else:
                    new_dp[j] = dp[j] or new_dp[j-1]
            i += 1
        elif c == '?':
            for j in range(1, t_len + 1):
                if dp[j-1]:
                    new_dp[j] = True
