            while j < n and pattern[j] != ']':
                j += 1
            content = pattern[start:j]
            ranges = []
            k = 0
            clen = len(content)
            while k < clen:
                if k + 2 < clen and content[k+1] == '-':
                    ranges.append((content[k], content[k+2]))
                    k += 3
                else:
                    ranges.append((content[k], content[k]))
                    k += 1
