    return dp[n_txt]

def lis(nums: list[int]) -> list[int]:
    n = len(nums)
    if n == 0:
        return []

    # dp[i] stores the length of the longest increasing subsequence starting at index i
    dp = [1] * n
    for i in range(n - 1, -1, -1):
        current_max = 0
        for j in range(i + 1, n):
            if nums[j] > nums[i]:
                if dp[j] > current_max:
                    current_max = dp[j]
        dp[i] = 1 + current_max

    max_len = 0
    for x in dp:
        if x > max_len:
            max_len = x

    if max_len == 0:
        return []

    res = []
    last_idx = -1
    last_val = -float('inf')
    needed_len = max_len

    # We need to pick max_len elements
    for _ in range(max_len):
        best_val = None
        best_idx = -1

        # Scan for candidates
        for i in range(last_idx + 1, n):
            if nums[i] > last_val and dp[i] == needed_len:
                if best_val is None or nums[i] < best_val or (nums[i] == best_val and i < best_idx):
                    best_val = nums[i]
                    best_idx = i

        # Append and update
        res.append(best_val)
        last_idx = best_idx
        last_val = best_val
        needed_len -= 1

    return res

