    # starting at index i.
    dp = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if nums[j] > nums[i]:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1

    max_len = max(dp)
    res = []
    prev_val = None
    prev_idx = -1
    needed = max_len

    for _ in range(max_len):
        best_val = None
        best_idx = -1
        # Greedily pick the smallest valid next value.
        # Ties in value are broken by picking the earliest index,
        # which maximizes future options and preserves lexicographical minimality.
        for j in range(prev_idx + 1, n):
            if (prev_val is None or nums[j] > prev_val) and dp[j] == needed:
                if best_val is None or nums[j] < best_val or (nums[j] == best_val and j < best_idx):
                    best_val = nums[j]
                    best_idx = j
        res.append(best_val)
        prev_val = best_val
        prev_idx = best_idx
        needed -= 1

    return res

