def shortest_path(n: int, edges: list[tuple[int, int, int]], src: int, dst: int) -> tuple[int, list[int]]:
    if src == dst:
        return (0, [src])

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    INF = float('inf')
    # dist[v] stores the best (weight, num_edges, path_tuple) found so far
    dist = [(INF, INF, ())] * n
    dist[src] = (0, 0, (src,))

    # Priority queue stores (weight, num_edges, path_tuple, current_node)
    pq = [(0, 0, (src,), src)]

    while pq:
        w, e, p, u = heapq.heappop(pq)

        # If we popped a path that is worse than the best known path to u, skip it
        if (w, e, p) != dist[u]:
            continue

        if u == dst:
            return (w, list(p))

        for v, weight in adj[u]:
            new_w = w + weight
            new_e = e + 1
            new_p = p + (v,)
            # Update if we found a strictly better path according to the criteria
            if (new_w, new_e, new_p) < dist[v]:
                dist[v] = (new_w, new_e, new_p)
                heapq.heappush(pq, (new_w, new_e, new_p, v))

    return (-1, [])

