def knapsack(items: list[tuple[int, int]], cap: int) -> list[int]:
    n = len(items)
    # dp[i][c] stores the maximum value achievable using items i..n-1 with capacity c
    dp = [[0] * (cap + 1) for _ in range(n + 1)]

    # Fill DP table backwards
    for i in range(n - 1, -1, -1):
        w, v = items[i]
        for c in range(cap + 1):
            dp[i][c] = dp[i+1][c]  # Skip item i
            if c >= w:
                take = dp[i+1][c - w] + v
                if take > dp[i][c]:
                    dp[i][c] = take

    # Reconstruct the lexicographically smallest optimal index list
    result = []
    curr_cap = cap
    for i in range(n):
        w, v = items[i]
        if curr_cap >= w:
            # Prefer taking item i if it's part of an optimal solution.
            # Since we process indices in increasing order, taking i yields a 
            # lexicographically smaller index list than skipping it when values are equal.
            if dp[i+1][curr_cap - w] + v >= dp[i+1][curr_cap]:
                result.append(i)
                curr_cap -= w

    return result

def knapsack(items: list[tuple[int, int]], cap: int) -> list[int]:
    n = len(items)
    # dp[i][w] stores the maximum value achievable using a subset of items[i:] with capacity w
    dp = [[0] * (cap + 1) for _ in range(n + 1)]

    # Fill DP table from bottom to top
    for i in range(n - 1, -1, -1):
        w_i, v_i = items[i]
        for w in range(cap + 1):
            dp[i][w] = dp[i+1][w]
            if w >= w_i:
                val = v_i + dp[i+1][w - w_i]
                if val > dp[i][w]:
                    dp[i][w] = val

    # Reconstruct the solution greedily for lexicographically smallest index list
    res = []
    w = cap
    for i in range(n):
        w_i, v_i = items[i]
        # Include item i if it maintains the optimal value
        if w >= w_i and dp[i][w] == v_i + dp[i+1][w - w_i]:
            res.append(i)
            w -= w_i

    return res

