def decimal_to_fraction(x: str) -> str:
    neg = x.startswith('-')
    if neg:
        x = x[1:]

    if '.' in x:
        int_part_str, frac_part = x.split('.', 1)
    else:
        int_part_str = x
        frac_part = ""

    if '(' in frac_part:
        a_str, rest = frac_part.split('(', 1)
        b_str = rest.rstrip(')')
    else:
        a_str = frac_part
        b_str = ""

    I = int(int_part_str) if int_part_str else 0
    A_val = int(a_str) if a_str else 0
    B_val = int(b_str) if b_str else 0

    k = len(a_str)
    m = len(b_str)

    if m == 0:
        num = I * (10 ** k) + A_val
        den = 10 ** k
    else:
        num = (I * (10 ** (k + m)) + A_val * (10 ** m) + B_val) - (I * (10 ** k) + A_val)
        den = (10 ** (k + m)) - (10 ** k)

    if neg:
        num = -num

    if num == 0:
        return "0/1"

    g = math.gcd(abs(num), den)
    return f"{num // g}/{den // g}"

