def decimal_to_fraction(x: str) -> str:
    sign = ""
    s = x
    if s.startswith("-"):
        sign = "-"
        s = s[1:]

    if "." in s:
        int_part, frac_part = s.split(".", 1)
    else:
        int_part = s
        frac_part = ""

    if not int_part:
        int_part = "0"

    if "(" in frac_part:
        non_rep, rep = frac_part.split("(", 1)
        rep = rep[:-1]
    else:
        non_rep = frac_part
        rep = ""

    if not rep:
        num = int(int_part + non_rep)
        den = 10 ** len(non_rep)
    else:
        num = int(int_part + non_rep + rep) - int(int_part + non_rep)
        den = (10 ** len(non_rep)) * ((10 ** len(rep)) - 1)

    if sign == "-":
        num = -num

    if num == 0:
        return "0/1"

    g = math.gcd(abs(num), den)
    num //= g
    den //= g

    return f"{num}/{den}"

