def decode_ways(s: str) -> int:
    MOD = 1_000_000_007
    n = len(s)
    if n == 0:
        return 0

    # dp[i] represents the number of ways to decode the prefix s[:i]
    # We only need the previous two values, but an array is cleaner and fits memory limits.
    dp = [0] * (n + 1)
    dp[0] = 1

    # Base case for first character
    c1 = s[0]
    if c1 == '*':
        dp[1] = 9
    elif c1 != '0':
        dp[1] = 1
    else:
        dp[1] = 0

    for i in range(2, n + 1):
        c1 = s[i-1]
        c2 = s[i-2]

        ways = 0

        # Case 1: Single digit decoding (current char)
        single_count = 0
        if c1 == '*':
            single_count = 9
        elif c1 != '0':
            single_count = 1

        if single_count > 0:
            ways = (ways + dp[i-1] * single_count) % MOD

        # Case 2: Two digit decoding (previous two chars)
        double_count = 0
        if c2 == '*' and c1 == '*':
            double_count = 15  # 11-19 (9) + 21-26 (6)
        elif c2 == '*' and c1 != '*':
            # c2 is *, c1 is digit
            # Valid numbers: 10+c1_digit, 20+c1_digit
            # 10+c1 is always valid (10-19)
            # 20+c1 is valid if c1 <= 6
            if c1 <= '6':
                double_count = 2
            else:
                double_count = 1
        elif c2 != '*' and c1 == '*':
            # c2 is digit, c1 is *
            # c2 can be 1 or 2 to form valid 2-digit numbers
            if c2 == '1':
                double_count = 9  # 11-19
            elif c2 == '2':
                double_count = 6  # 21-26
            else:
                double_count = 0
        else:
            # Both are digits
            val = int(c2 + c1)
            if 10 <= val <= 26:
                double_count = 1

        if double_count > 0:
            ways = (ways + dp[i-2] * double_count) % MOD

        dp[i] = ways

    return dp[n]

