            two = 15
        elif c1 == '*':
            two = 2 if c2 <= '6' else 1
        elif c2 == '*':
            two = 9 if c1 == '1' else (6 if c1 == '2' else 0)
        else:
            if 10 <= int(c1 + c2) <= 26:
