        if c1 == '0':
            # '0' cannot be a single character code
            pass
        elif c1 == '*':
            # '*' can be '1' through '9'
            ways = (ways + 9 * dp[i-1]) % MOD
        else:
            # c1 is '1'-'9'
            ways = (ways + dp[i-1]) % MOD

        # Option 2: Decode c2c1 as a two-character code (10-26)
        # Valid if the number formed is between 10 and 26 inclusive.

        if c1 == '0':
            # Must be 10 or 20. c2 must be '1' or '2'.
            if c2 == '1' or c2 == '2':
                ways = (ways + dp[i-2]) % MOD
            elif c2 == '*':
                # '*' can be '1' (making 10) or '2' (making 20)
                ways = (ways + 2 * dp[i-2]) % MOD
        elif c1 in '123456':
            # c1 is 1-6.
            # 11-16 valid (c2='1')
            # 21-26 valid (c2='2')
            if c2 == '1':
                ways = (ways + dp[i-2]) % MOD
            elif c2 == '2':
                ways = (ways + dp[i-2]) % MOD
            elif c2 == '*':
                # '*' can be '1' (11-16) or '2' (21-26)
                ways = (ways + 2 * dp[i-2]) % MOD
        elif c1 in '789':
            # c1 is 7-9.
            # 17-19 valid (c2='1')
            # 27-29 invalid (c2='2')
            if c2 == '1':
                ways = (ways + dp[i-2]) % MOD
            elif c2 == '*':
                # '*' can be '1' (17-19). '2' would make 27-29 invalid.
                ways = (ways + 1 * dp[i-2]) % MOD
        elif c1 == '*':
            # c1 is wildcard 1-9.
            if c2 == '1':
                # 11-19 are all valid. 9 possibilities.
                ways = (ways + 9 * dp[i-2]) % MOD
            elif c2 == '2':
